import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import { authLogin, authRegister, getProfile } from '../services/api';

const AuthContext = createContext();

export function AuthProvider({ children }) {
  const [user, setUser] = useState(() => {
    const raw = localStorage.getItem('user');
    return raw ? JSON.parse(raw) : null;
  });
  const [token, setToken] = useState(() => localStorage.getItem('token') || null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (token && !user) {
      // try to refresh profile
      (async () => {
        try {
          const res = await getProfile();
          setUser(res.data.user || null);
          localStorage.setItem('user', JSON.stringify(res.data.user || null));
        } catch (e) {
          setUser(null);
          setToken(null);
          localStorage.removeItem('token');
          localStorage.removeItem('user');
        }
      })();
    }
  }, [token]);

  const login = async (email, password) => {
    setLoading(true);
    try {
      const res = await authLogin(email, password);
      const t = res.data.token;
      const u = res.data.user;
      setToken(t);
      setUser(u);
      localStorage.setItem('token', t);
      localStorage.setItem('user', JSON.stringify(u));
      return res;
    } finally {
      setLoading(false);
    }
  };

  const register = async (firstName, lastName, email, password) => {
    setLoading(true);
    try {
      const res = await authRegister(firstName, lastName, email, password);
      const t = res.data.token;
      const u = res.data.user;
      setToken(t);
      setUser(u);
      localStorage.setItem('token', t);
      localStorage.setItem('user', JSON.stringify(u));
      return res;
    } finally {
      setLoading(false);
    }
  };

  const logout = useCallback(() => {
    setToken(null);
    setUser(null);
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    // allow other parts of app to react
    window.location.href = '/login';
  }, []);

  useEffect(() => {
    const handler = () => {
      logout();
    };
    window.addEventListener('auth:logout', handler);
    return () => window.removeEventListener('auth:logout', handler);
  }, [logout]);

  return (
    <AuthContext.Provider value={{ user, token, loading, login, register, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}
